def clean(s):
    return re.sub(r'[^a-z0-9\s]', ' ', s.lower())

s_words = clean(source).split()
d_words = clean(draft).split()

# Find all matching sequences of length >= 6
matches = []
for i in range(len(d_words)):
    for j in range(len(s_words)):
        k = 0
        while (i + k < len(d_words)) and (j + k < len(s_words)) and (d_words[i + k] == s_words[j + k]):
            k += 1
        if k >= 6:
            match_str = " ".join(d_words[i:i+k])
            matches.append((k, match_str, i))

# De-duplicate matches
unique_matches = {}
for length, text, pos in sorted(matches, key=lambda x: x[0], reverse=True):
    # check if subsumed
    if not any(text in existing for existing in unique_matches):
        unique_matches[text] = length

for text, length in unique_matches.items():
    print(f"Match ({length} words): '{text}'")

